use std::{env,fs,path::PathBuf};
fn main() {
    println!("cargo:rerun-if-changed=build-input.txt");
    let text=fs::read_to_string("build-input.txt").unwrap();
    let value:u64=text.trim().parse().unwrap();
    fs::write(PathBuf::from(env::var_os("OUT_DIR").unwrap()).join("generated.rs"),
        format!("pub const BUILD_VALUE: u64 = {};\n",value)).unwrap();
}
